import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·16","description":"易小帖 - 卷三·16","frontmatter":{"title":"卷三·16","description":"易小帖 - 卷三·16"},"headers":[],"relativePath":"classics/yixiaotie/084.md","filePath":"classics/yixiaotie/084.md"}'),o={name:"classics/yixiaotie/084.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·16",tabindex:"-1"},[r("卷三·16 "),e("a",{class:"header-anchor",href:"#卷三·16","aria-label":"Permalink to “卷三·16”"},"​")],-1),e("p",null,"揚子《太玄》分大衍之數以三八為木，四九為金，二七為火，一六為水，五五為土，此即鄭氏大衍之註所由昉。但鄭氏一六合水，二七合火，三八合木，四九合金，五十合土，一生一成，俱全舉其數。而《太玄》五五生成兼併，在五則有名而欠其實，在十則得實而亡其名，蓋以生數之極即成數之本，故六七八九俱從五數重累之，如五加一則為六，故六與一合，以六即一也。五加二則為七，故七與二合，以七即二也。至加三為八，加四為九皆然，則五加五為十，不必言十，而十在其中，以五五即十也，亦不必言五而五在其中，以五五為十則一五為五也。故夫子言大衍之數，明知為五十有五，而實指其數，然又闕五數，而曰五十，則正以生成全數，本末交互處概言之，以合之揲蓍之策已耳。若太乙下九宮法，今之冒稱洛書者，謂太乙不再居中宮，而有五無十，則又失大衍數矣。揚子五五正與夫子說有合，而予作《仲氏易》時，仍不用之者，以五位相得本文自具，必欲暴白其闕五之故，恐聖言亦無是耳。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
